def transform(g):
    h,w=len(g),len(g[0])
    # full-height constant column separator
    for j in range(w):
        if len(set(r[j] for r in g))==1 and j==w-1-j:
            a=[r[:j] for r in g]; b=[r[j+1:] for r in g]
            return [[3 if a[i][k]==b[i][k] else 4 for k in range(j)] for i in range(h)]
    # full-width constant row separator: template below, patterns above
    for i in range(h):
        if len(set(g[i]))==1:
            tmpl=g[i+1:]
            top=g[:i]
            # split top by constant columns within it
            seps=[j for j in range(w) if len(set(r[j] for r in top))==1]
            segs=[]; start=0
            for j in seps+[w]:
                if start<j: segs.append((start,[r[start:j] for r in top]))
                start=j+1
            out=[[None]*w for _ in tmpl]
            for s,blk in segs:
                for ii in range(len(tmpl)):
                    for jj in range(len(blk[0])):
                        out[ii][s+jj]=3 if tmpl[ii][s+jj]==blk[ii][jj] else 4
            return out
